        ones=a.count(1); twos=a.count(2)
        # retain detailed structure when tile is already uniform
        if ones==9 or twos==9: continue
        v=1 if ones>=twos else 2
        for r in range(br,br+3):
          for c in range(bc,bc+3):
            if grid[r][c]!=v and (r+c)%3==0: out[r][c]=v
    return out"}

