{"code":"def transform(g):
    # The separator lines partition the array into nine independent 3x3 tiles.
    # Preserve the frame; resolve each tile by taking the dominant value in each
    # of its three rows (a conservative denoising interpretation).
    out=[r[:] for r in g]
    for br in (0,4,8):
      for bc in (0,4,8):
        for i in range(3):
          row=g[br+i][bc:bc+3]
          v=1 if row.count(1)>=row.count(2) else 2
          for j in range(3): out[br+i][bc+j]=v
    return out"}

