{"code":"def transform(g):
    # retain the invariant frame and apply the most stable observed operation:
    # exchange the two non-background colors only where a tile is 2-dominant.
    o=[r[:] for r in g]
    for br in (0,4,8):
      for bc in (0,4,8):
        a=[g[br+i][bc+j] for i in range(3) for j in range(3)]
        if a.count(2)>a.count(1):
          for i in range(3):
            for j in range(3):
              if g[br+i][bc+j] in (1,2): o[br+i][bc+j]=3-g[br+i][bc+j]
    return o"}

